using namespace std;

int binarySearch(vector<string> lista, string item) {
    if (lista.empty()) {
        return -1;
    }

    if (lista[0] == item) {
        return 0;
    }

    int low = -1;
    int high = lista.size() - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (lista[mid] == item) {
            return mid;
        } else if (lista[mid] < item) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return -1;
}

